<script setup lang="ts">import {ref} from 'vue'; import {issues as seed} from '../api/mock'; import StatusBadge from '../components/StatusBadge.vue'; const rows=ref(seed); const confirm=(id:number)=>{const r=rows.value.find(x=>x.id===id); if(r)r.status='已确认'};</script><template><section class="page"><div class="page-head"><div><h1>待确认异常</h1><p>只把真正需要人工判断的项目交给运营。</p></div></div><div class="card panel"><div class="table-wrap"><table><thead><tr><th>问题码</th><th>Campaign</th><th>问题</th><th>系统建议</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><code>{{r.code}}</code></td><td>{{r.campaign}}</td><td>{{r.problem}}</td><td>{{r.suggestion}}</td><td><StatusBadge :status="r.status==='已确认'?'READY':'NEEDS_REVIEW'"/></td><td><button class="link-btn" @click="confirm(r.id)">确认</button><button class="link-btn muted-action">修改</button></td></tr></tbody></table></div></div></section></template>
